return ['domain'=>'press-permit-core% 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);% 100 >= 3 && n % 100 <= 10 ? 3: n % 100 >= 11 ? 4 : 5);','plural-forms'=>'nplurals=6; plural=(n == 0 ? 0 : n == 1 ? 1 : n == 2 ? 2 : n % 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);','language'=>'ar100 >= 3 && n % 100 <= 10 ? 3: n % 100 >= 11 ? 4 : 5);','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:59+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'يتيح لك PublishPress Permissions تمكين أو رفض الوصول إلى المنشورات، الصفحات، الفئات، العلامات والمزيد.','PublishPress'=>'نشر الصحافة','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'تعديل الوسم لجميع أنواع المنشورات','Edit Tag for Posts'=>'تعديل الوسم للمنشورات','Advanced Custom Fields'=>'حقول مخصصة متقدمة','Control front-end access to Field Groups with advanced permission management.'=>'تحكم في وصول الواجهة الأمامية إلى مجموعات الحقول مع إدارة الأذونات المتقدمة.','Control access to Field Groups'=>'تحكم في الوصول إلى مجموعات الحقول','Front-end visibility restrictions'=>'قيود رؤية الواجهة الأمامية','Integration with permission groups'=>'تكامل مع مجموعات الأذونات','Beaver Builder'=>'باني بيفر','Compatibility with Edit Permissions in Beaver Builder.'=>'توافق مع تعديل الأذونات في باني بيفر.','Beaver editor integration'=>'تكامل محرر بيفر','Widget-level permission controls'=>'تحكم في أذونات مستوى الودجت','Template access restrictions'=>'قيود الوصول إلى القوالب','bbPress Forums'=>'منتديات bbPress','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'أذونات محددة للمنتدى لـ bbPress مع تحكم مفصل في وصول المنتدى والمشاركة.','Forum-specific permissions'=>'أذونات محددة للمنتدى','Topic creation restrictions'=>'قيود إنشاء الموضوعات','Forum access controls'=>'تحكم الوصول إلى المنتدى','BuddyPress'=>'BuddyPress','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'تعيين أذونات المنشورات والمصطلحات لمجموعات BuddyPress من أجل تحسين التحكم في المحتوى.','Assign post permissions to BuddyPress groups'=>'تعيين أذونات المنشورات لمجموعات BuddyPress','Assign term permissions to BuddyPress groups'=>'تعيين أذونات المصطلحات لمجموعات BuddyPress','Group-based content permissions'=>'أذونات المحتوى المستندة إلى المجموعات','CMS Tree View'=>'عرض شجرة CMS','Compatibility with Edit Permissions in CMS Tree View.'=>'التوافق مع تحرير الأذونات في عرض شجرة CMS.','Permission-aware tree view'=>'عرض شجرة مدرك للأذونات','Hierarchical content controls'=>'تحكمات المحتوى الهرمية','Elementor'=>'Elementor','Compatibility with Edit Permissions in Elementor.'=>'التوافق مع تحرير الأذونات في Elementor.','Elementor editor integration'=>'تكامل محرر Elementor','The Events Calendar'=>'تقويم الفعاليات','Apply permission controls to events and event-related content.'=>'تطبيق تحكمات الأذونات على الفعاليات والمحتوى المتعلق بالفعاليات.','Event post permissions'=>'أذونات منشورات الفعاليات','Event taxonomy controls'=>'تحكمات تصنيف الفعاليات','Nested Pages'=>'صفحات متداخلة','Compatibility with Edit Permissions in Nested Pages.'=>'التوافق مع تحرير الأذونات في الصفحات المتداخلة.','Permission-aware nested view'=>'عرض متداخل يدرك الأذونات','Quick edit integration'=>'تكامل التعديل السريع','PublishPress Statuses'=>'حالات PublishPress','Compatibility with PublishPress Statuses plugin.'=>'التوافق مع إضافة حالات PublishPress.','Custom status permissions'=>'أذونات الحالة المخصصة','Workflow-specific access controls'=>'ضوابط الوصول الخاصة بسير العمل','Status-based editing capabilities'=>'قدرات التحرير المعتمدة على الحالة','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'تصفية نتائج البحث استنادًا إلى أذونات العرض لاكتشاف المحتوى بشكل آمن.','Search result filtering'=>'تصفية نتائج البحث','Permission-aware indexing'=>'فهرسة تدرك الأذونات','Secure content discovery'=>'اكتشاف المحتوى الآمن','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'التوافق مع تصفية مصطلحات SearchWP لقدرات البحث المتقدمة.','Permission-aware search results'=>'نتائج البحث التي تدرك الأذونات','Term-based filtering'=>'تصفية قائمة على المصطلحات','Advanced search controls'=>'ضوابط البحث المتقدمة','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'تطبيق ضوابط الأذونات على منتجات WooCommerce وفئات المنتجات.','Product permissions'=>'أذونات المنتج','Product category controls'=>'تحكمات فئة المنتج','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'دعم متعدد اللغات مع مزامنة الأذونات عبر ترجمات المحتوى.','Permission synchronization across translations'=>'مزامنة الأذونات عبر الترجمات','Language-specific content access'=>'الوصول إلى المحتوى المحدد حسب اللغة','Multilingual permission management'=>'إدارة الأذونات متعددة اللغات','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'استبعاد المشاركات المقيدة من خرائط الموقع XML للحفاظ على فهرسة SEO بشكل صحيح.','Sitemap filtering for restricted content'=>'تصفية خرائط الموقع للمحتوى المقيد','Search engine visibility controls'=>'تحكمات رؤية محرك البحث','Permission-aware XML sitemaps'=>'خرائط موقع XML المدركة للأذونات','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'التوافق مع منشئ YooTheme وأذونات المصطلحات.','Builder interface compatibility'=>'توافق واجهة المنشئ','Term permission integration'=>'دمج أذونات المصطلح','Template access controls'=>'تحكمات وصول القالب','Viewing'=>'عرض','Access Circles'=>'دوائر الوصول','Editing Permissions'=>'أذونات التحرير','Compatibility Pack'=>'حزمة التوافق','Teaser'=>'مقدمة','File Access'=>'وصول الملفات','Membership'=>'العضوية','User Posts'=>'مشاركات المستخدم','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'دوائر الرؤية ودوائر التحرير تمنع الوصول إلى المحتوى الذي لم يؤلفه أعضاء المجموعة الآخرين.','Post-specific and category-specific permissions for creation and editing.'=>'إذن خاص بالمنشورات وإذن خاص بالفئات لإنشاء وتحرير المحتوى.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'التكامل مع ACF، bbPress، BuddyPress، Relevanssi، WPML وملحقات أخرى؛ دعم محسّن لمواقع متعددة.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'على واجهة الموقع الأمامية، عرض نص تشويقي للمنشورات غير القابلة للقراءة بدلاً من إخفائها.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'تقييد طلبات الملفات المباشرة استنادًا إلى وصول المستخدم إلى الصفحة المرتبطة بالملف.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'تخصيصات وصول محدودة زمنياً عن طريق تأخير أو انتهاء صلاحية عضوية مجموعة الأذونات.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'إنشاء صفحة تلقائيًا لكل مستخدم من الأدوار المحددة. متوافق مع العديد من ملحقات الفريق / الموظفين.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'دوائر الرؤية ودوائر التحرير تمنع الوصول إلى المحتوى الذي لم يؤلفه أعضاء المجموعة الآخرين. يمكن وضع علامة على أي دور في WP، مجموعة BuddyPress أو مجموعة مخصصة كدائرة لأنواع المنشورات المحددة.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'يدعم أذونات محددة للمحتوى للتعديل، تعيين المصطلحات واختيار الوالد للصفحة. بالاقتران مع وحدات أخرى، يدعم حالات سير العمل وPublishPress وPublishPress Revisions.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'يضيف التوافق أو التكامل مع ACF، bbPress، Relevanssi، عرض صفحة شجرة CMS، واجهة نوع المنشور المخصصة، Subscribe2، WPML، وملحقات أخرى متنوعة. قم بتكوين أي مجموعة BuddyPress كـ مجموعة أذونات. لمواقع متعددة، يوفر مجموعات أذونات على مستوى الشبكة.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'على واجهة الموقع الأمامية، استبدال المحتوى غير القابل للقراءة بنص بديل. يمكن تمكينه لأي نوع منشور. يتم توفير عوامل تصفية مخصصة ولكن لا يتطلب الأمر برمجة للاستخدام الأساسي.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'تصفية الوصول المباشر إلى الملفات، استنادًا إلى وصول المستخدم إلى المنشورات التي يرتبط بها الملف. لا يتطلب تكوين إضافي. ينشئ/يعدل ملف .htaccess في مجلد التحميلات (وفي المجلد الرئيسي لمواقع متعددة).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'يسمح بأن تكون عضوية مجموعة الأذونات محدودة بالتاريخ (مؤجلة و/أو مجدولة لانتهاء الصلاحية). واجهة اختيار تاريخ بسيطة بجانب اختيار عضوية المجموعة.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'إنشاء أو مزامنة المنشورات لتتناسب مع المستخدمين. مصمم لملحقات الفريق / الموظفين، ولكن مع إمكانيات استخدام واسعة.','If you like %s, please leave us a %s rating. Thank you!'=>'إذا أعجبك %s، يرجى ترك لنا تقييم %s. شكراً لك!','About PublishPress Permissions'=>'حول أذونات PublishPress','About'=>'حول','Permissions Documentation'=>'وثائق الأذونات','Documentation'=>'وثائق','Contact the PublishPress team'=>'اتصل بفريق PublishPress','Contact'=>'اتصال','Permission Group'=>'مجموعة الأذونات','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'أذونات محددة: القيود (\'محظور\') تأخذ الأولوية على الإضافات (\'مفعل\').','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'الأذونات المحددة: لا يمكن تطبيق قيود (\'محظور\') على المجموعات المعرفة مخصصًا','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'تعيين الأدوار الإضافية متاح لمجموعات {All} و {Anonymous}','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'السماح لمجموعات الميتا {All} و {Anonymous} بالحصول على أذونات قراءة محددة للمحتوى الخاص','Users who have specific editing permissions for a post or attachment can also delete it'=>'يمكن للمستخدمين الذين لديهم أذونات تحرير محددة لمنشور أو مرفق أيضًا حذفه','Users who have custom editing permissions for an attachment can also delete it'=>'يمكن للمستخدمين الذين لديهم أذونات تحرير مخصصة لمرفق أيضًا حذفه','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'تعطيل تصفية الواجهة الأمامية إذا كان المستخدم المسجل مسؤول محتوى (عادةً ما تتطلب التصفية إدراج المنشورات الخاصة القابلة للقراءة في قائمة get_pages()، وعدد المنشورات، إلخ.)','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'تعطيل تصفية الواجهة الأمامية لجميع المستخدمين (مع مراعاة القيود بواسطة PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'قائمة مفصولة بفواصل لأنواع المنشورات لتقييد تأثير PP_UNFILTERED_FRONT وتطبيق_filters( \'presspermit_skip_cap_filtering\' )','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'الأذونات المحددة: الإضافات (\'مفعل\') لا تُطبق، ولا يمكن تعيينها','Don\'t assign or apply specific permissions for the \'post\' type'=>'لا تعين أو تطبق أذونات محددة لنوع \'مشاركة\'','Don\'t assign or apply specific permissions for the \'page\' type'=>'لا تعين أو تطبق أذونات محددة لنوع \'صفحة\'','Don\'t assign or apply specific permissions for the \'media\' type'=>'لا تعين أو تطبق أذونات محددة لنوع \'وسائط\'','Don\'t assign or apply specific permissions for the specified custom post type'=>'لا تقم بتعيين أو تطبيق أذونات محددة لنوع المنشور المخصص المحدد','Include scheduled posts in the posts query if user can edit them'=>'قم بتضمين المشاركات المجدولة في استعلام المشاركات إذا كان بإمكان المستخدم تعديلها','Don\'t filter term post counts in get_terms() call'=>'لا تقم بتصفية حسابات المشاركات للمصطلحات في استدعاء get_terms()','Leave unreadable posts on WP Navigation Menus'=>'اترك المشاركات غير القابلة للقراءة في قوائم التنقل الخاصة بـ WP','Don\'t apply CSS to hide empty Nav Menus'=>'لا تطبق CSS لإخفاء قوائم التنقل الفارغة','For legacy Nav Menus, hide empty nav menu div'=>'للقوائم القديمة، اخفِ div قائمة التنقل الفارغ','Leave terms with no readable posts on WP Navigation Menus'=>'اترك المصطلحات التي لا تحتوي على مشاركات قابلة للقراءة في قوائم التنقل الخاصة بـ WP','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'عند تطبيق Teaser مع تفعيل إعادة التوجيه، أضف عنوان URL الأصلي كوسيلة إعادة توجيه','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'للتوافق مع Teaser، حدد وسيط إعادة التوجيه للاستخدام بدلاً من redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'للتوافق مع Teaser، حدد وسيط إعادة توجيه إضافي بخلاف redirect_to','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'للتوافق مع Teaser، منع إضافة وسيط pp_permissions إلى عمليات إعادة التوجيه','Filter priority for \'get_pages\' filter (default: 1)'=>'أولوية التصفية لفلتر \'get_pages\' (افتراضي: 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'لا تشمل الصفحات الخاصة القابلة للقراءة في أداة الصفحات أو نتائج wp_list_pages() / get_pages()    ','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'إذا تم كتم بعض الصفحات من نتائج get_pages()، قم بتغيير قيم post_parent المقابلة للصفحات الفرعية إلى سلف مرئي','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'لا تعدل أبدًا قيمة post_parent في مجموعة نتائج get_pages()، حتى إذا تم كتم بعض الصفحات','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'لتحسين الأداء، قم بتغيير استعلام قاعدة بيانات get_pages() لإرجاع مجموعة فرعية من الحقول، مستثنيًا post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'لا تطبق teaser المحتوى على نتائج get_pages() (اترك المنشورات غير القابلة للقراءة مخفية)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'إذا تم كتم بعض المصطلحات من نتائج get_terms()، قم بتغيير قيم الأبوين المقابلة للمصطلحات الفرعية إلى سلف مرئي','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'لا تعدل أبدًا قيمة الأبوين في مجموعة نتائج get_terms()، حتى إذا تم كتم بعض المصطلحات','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'تعيين المؤلف للمستخدم الحالي إذا كانت القدرة autoset_post_author / autoset_page_author مخصصة','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'ترك مكتبة الوسائط بمعايير وصول عادية بناءً على قدرات دور المستخدم','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'توفير حلول رفع الواجهة الأمامية التي تتطلب قدرات تحرير الصفحات لطلب الرفع غير المتزامن','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'معاملة الوسائط المرفقة بأنواع المشاركات غير المسجلة على أنها غير مرفقة، لتجنب الفلترة غير الصحيحة والمربكة','Attached Files Private setting available'=>'إعداد الملفات المرفقة خاص متاح','Comma-separated list of mime types to exclude from File Access filtering'=>'قائمة تفصيلية مفصولة بفواصل لأنواع mime لاستبعادها من تصفية وصول الملفات','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'قائمة مفصولة بفواصل من أنواع MIME لتضمينها في تصفية وصول الملفات (تجاوز الآخرين)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'عند حظر الوصول إلى الملفات، لا تقم بتعيين خاصية WP_Query 404 / 403','HTTP status code to send when file access is blocked'=>'رمز حالة HTTP لإرساله عند حظر الوصول إلى الملفات','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'في قائمة المستخدمين، تعتبر مجموعات الأذونات في العمود المخصص روابط تصفية القائمة بدلاً من روابط تحرير المجموعة','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'فتح الأذونات > الإعدادات > الأساسية > الواجهة الخلفية للإدارة > \'إخفاء المشاركات غير القابلة للتحرير\'','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'داخل سكربت async-upload.php، تصفية استرجاع المؤلف للمرفق الذي تم رفعه للتو','Don\'t filter comment display or moderation within wp-admin'=>'لا تقم بتصفية عرض التعليقات أو الإدارة ضمن wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'السماح بإضافة المسؤولين إلى مجموعات الأذونات، حتى لو لم يكونوا مقيدين','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'إذا كانت الأذونات المتداولة مخصصة لفرع صفحة، استبدل أي أذونات مخصصة بوضوح في الصفحات الفرعية','Max number of specific permissions to insert in a single database query (default 1000)'=>'الحد الأقصى لعدد الأذونات المحددة لإدراجها في استعلام قاعدة بيانات واحد (الافتراضي 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'لا تقم بتعديل فهارس قائمة المسؤول لتحديد موقع قائمة الأذونات تحت المستخدمين','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'لا تضف قائمة أذونات. بدلاً من ذلك، أضف عناصر قائمة إلى قوائم المستخدمين والإعدادات.','Customize Permissions screen title for Groups'=>'تخصيص عنوان شاشة الأذونات للمجموعات','Customize Permission Groups caption on user profile'=>'تخصيص عنوان مجموعات الأذونات في ملف تعريف المستخدم','Only one group is selectable on Add User screen'=>'يمكن اختيار مجموعة واحدة فقط في شاشة إضافة مستخدم','Only one group is selectable on Edit User screen'=>'يمكن اختيار مجموعة واحدة فقط في شاشة تعديل المستخدم','Display a custom hint on Permissions > User Groups'=>'عرض تلميح مخصص على الأذونات > مجموعات المستخدمين','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'الحد الأقصى لعدد المشاركات / المصطلحات غير الهيكلية لعرضها في وقت واحد (لكل صفحة)','Max number of hierarchical posts / terms to display at one time (per page)'=>'أقصى عدد من المشاركات / المصطلحات الهرمية لعرضها في وقت واحد (لكل صفحة)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'تعطيل التحديد التلقائي لعدد مستويات شجرة الصفحة لجعلها مرئية افتراضيًا. بدلاً من ذلك، استخدم القيمة المحددة.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'عدد الصفحات / المصطلحات المرئية المستهدفة، المستخدمة للتحديد التلقائي لعدد المستويات المرئية','Make search function on the post selection metabox look at post content'=>'اجعل وظيفة البحث في مربع تحديد المشاركة تبحث في محتوى المشاركة','Make search function on the post selection metabox look at post excerpt'=>'اجعل وظيفة البحث في مربع تحديد المشاركة تبحث في مقتطف المشاركة','Search by last name instead of display name'=>'البحث بواسطة الاسم الأخير بدلاً من اسم العرض','User field to search by default'=>'حقل المستخدم للبحث بشكل افتراضي','User meta fields selectable for search (comma-separated)'=>'حقول بيانات التعريف للمستخدم القابلة للاختيار للبحث (مفصولة بفواصل)','User meta fields which should be treated as numeric (comma-separated)'=>'حقول بيانات التعريف للمستخدم التي يجب اعتبارها رقمية (مفصولة بفواصل)','User meta fields which should be treated as boolean (comma-separated)'=>'حقول بيانات التعريف للمستخدم التي يجب اعتبارها منطقية (مفصولة بفواصل)','Use display name for search results instead of user_login'=>'استخدم اسم العرض لنتائج البحث بدلاً من user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'عند مزامنة المجموعات الميتاجroup للدور مع الأدوار المعرفة حاليًا في WP، لا تحذف المجموعات للأدوار المعرفة سابقًا في WP.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'فرض اكتشاف أدوار مستخدمي WP التي تضاف ديناميكيًا ولكن لا يتم تخزينها في قاعدة بيانات WP.','To save memory on front end access, don\'t register any filters related to content editing'=>'لتوفير الذاكرة على وصول الواجهة الأمامية، لا تقم بتسجيل أي فلاتر تتعلق بتحرير المحتوى','Attached media do not have any comments, so don\'t append clauses to comment queries for them'=>'الوسائط المرفقة لا تحتوي على أي تعليقات، لذا لا تضف بنودًا لاستعلامات التعليقات لها','Reduce overhead of pages query (in get_pages() and wp-admin) by defaulting fields to a set list that does not include post_content '=>'تقليل التحميل الزائد لاستعلامات الصفحات (في get_pages() و wp-admin) عن طريق تعيين الحقول إلى قائمة محددة لا تشمل محتوى المشاركة','Reduce overhead of wp-admin posts query by defaulting fields to a set list that does not include post_content '=>'تقليل العبء على استعلامات wp-admin للمشاركات عن طريق تعيين الحقول لقائمة محددة لا تتضمن post_content','Reduce overhead of wp-admin Media query by defaulting fields to a set list that does not include post_content '=>'تقليل العبء على استعلامات wp-admin للوسائط عن طريق تعيين الحقول لقائمة محددة لا تتضمن post_content','Reduce overhead of wp-admin query for specified custom post type by defaulting fields to a set list that does not include post_content '=>'تقليل العبء على استعلام wp-admin لنوع المنشور المخصص المحدد عن طريق تعيين الحقول لقائمة محددة لا تتضمن post_content','Work around database setup warnings (at plugin activation) on some servers'=>'التغلب على تحذيرات إعداد قاعدة البيانات (عند تنشيط الإضافة) على بعض الخوادم','Development use only (suppresses post_status = \'publish\' clause for unfiltered post types with anonymous user)'=>'للاستخدام في التطوير فقط (يقوم بإلغاء شرط post_status = \'publish\' لأنواع المنشورات غير المفلترة مع مستخدم مجهول)','Development use only (on front end, do not replace \'post_status = \'publish\'\' clause with filtered equivalent)'=>'للاستخدام في التطوير فقط (على الواجهة الأمامية، لا تستبدل شرط \'post_status = \'publish\'\' بما يعادله المفلتر)','Logged In'=>'مسجل الدخول','Not Logged In'=>'غير مسجل الدخول','Everyone'=>'الجميع','Change Request Notifications'=>'إشعارات طلب التغيير','Submitted Revision Editors'=>'مراجعة مُقدمة','Scheduled Change Notifications'=>'إشعارات التغيير المجدولة','Scheduled Revision Monitors'=>'مراقبو المراجعة المجدولة','Authenticated site users, except for Administrators'=>'مستخدمو الموقع المعتمدون، باستثناء المشرفين','Anonymous users (not logged in)'=>'المستخدمون المجهولون (غير مسجلين الدخول)','All users (including anonymous)'=>'جميع المستخدمين (بما في ذلك المجهولون)','All users with the WordPress role of %s'=>'جميع المستخدمين الذين لديهم دور WordPress من %s','%1$s %2$s'=>'%1$s %2$s','%1$s won&#39;t work until you upgrade PHP to version %2$s or later. Current version: %3$s'=>'%1$s لن يعمل حتى تقوم بترقية PHP إلى الإصدار %2$s أو أحدث. الإصدار الحالي: %3$s','%1$s won&#39;t work until you upgrade %2$s to version %3$s or later.'=>'%1$s لن يعمل حتى تقوم بترقية %2$s إلى الإصدار %3$s أو أحدث.','%1$s won&#39;t work until you upgrade WordPress to version %2$s or later.'=>'%1$s لن يعمل حتى تقوم بترقية WordPress إلى الإصدار %2$s أو أحدث.','This version of %1$s cannot work with your current %2$s version. Please upgrade it to %3$s or later.'=>'هذه النسخة من %1$s لا يمكن أن تعمل مع إصدار %2$s الحالي لديك. يرجى ترقية الإصدار إلى %3$s أو أحدث.','Duplicate %1$s module activated (%2$s in folder %3$s).'=>'تم تفعيل وحدة %1$s المكررة (%2$s في المجلد %3$s).','Dismiss'=>'إزالة','Custom Group'=>'مجموعة مخصصة','Custom Groups'=>'مجموعات مخصصة','Groups'=>'المجموعات','(using default capabilities due to invalid %s definition)'=>'(استخدام قدرات افتراضية بسبب تعريف %s غير صالح)','%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s'=>'%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s','%1$s&nbsp;%2$s%3$s'=>'%1$s&nbsp;%2$s%3$s','Your license key has expired. For updates to PublishPress Permissions Pro and priority support, %splease renew%s.'=>'لقد انتهت صلاحية مفتاح الترخيص الخاص بك. للحصول على تحديثات لبرنامج PublishPress Permissions Pro والدعم ذو الأولوية، %sيرجى تجديده%s.','[WP %s]'=>'[WP %s]','All users with a WordPress %s role'=>'جميع المستخدمين الذين لديهم دور في ووردبريس %s','All users who are logged in and have a role on the site'=>'جميع المستخدمين الذين قاموا بتسجيل الدخول ولديهم دور على الموقع','Users to notify when revisions are submitted'=>'المستخدمون الذين يجب إبلاغهم عند تقديم التعديلات','Users to notify when scheduled revisions are published'=>'المستخدمون الذين يجب إبلاغهم عند نشر التعديلات المجدولة','(login timed out)'=>'(انتهت صلاحية تسجيل الدخول)','View'=>'عرض','Control assignment of selected terms to %s.'=>'تحكم في تعيين المصطلحات المحددة إلى %s.','Control if this %s can be selected as a Parent Page.'=>'تحكم إذا كان يمكن اختيار هذا %s كصفحة رئيسية.','Control editing of selected %s.'=>'تحكم في تحرير %s المحدد.','Control publishing of selected %s.'=>'تحكم في نشر %s المحدد.','Control deletion of selected %s.'=>'تحكم في حذف %s المحدد.','Control term management for selected %s.'=>'تحكم في إدارة المصطلحات لـ %s المحدد.','Control frontend viewing of selected %s.'=>'تحكم في عرض الواجهة الأمامية لـ %s المحدد.','Control who can create a revision of this %s.'=>'تحكم في من يمكنه إنشاء مراجعة لهذا %s.','Control who can submit a revision of this %s.'=>'تحكم في من يمكنه تقديم مراجعة لهذا %s.','Control which terms can be set as a Parent of other terms.'=>'تحكم في المصطلحات التي يمكن تعيينها كأب لمصطلحات أخرى.','Allow users to manage selected terms.'=>'السماح للمستخدمين بإدارة المصطلحات المحددة.','Control management of selected groups.'=>'تحكم في إدارة المجموعات المحددة.','Enable'=>'تفعيل','Block'=>'حظر','Limit to'=>'تحديد إلى','Expand access to allow specified items regardless of role capabilities or restrictions.'=>'توسيع الوصول للسماح بالعناصر المحددة بغض النظر عن قدرات أو قيود الأدوار.','Restrict access by blocking specified items unless an "Enabled" exception is also stored.'=>'تقييد الوصول عن طريق حظر العناصر المحددة ما لم يتم تخزين استثناء "مفعل" أيضًا.','Restrict access by limiting role capabilities to apply only for specified items. Users still need capabilities in their main role or extra roles.'=>'تقييد الوصول عن طريق تقييد قدرات الأدوار لتطبيقها فقط على العناصر المحددة. لا يزال يحتاج المستخدمون إلى القدرات في دورهم الرئيسي أو الأدوار الإضافية.','Using group membership to block access is not recommended. Consider reducing the user\'s role capabilities and using group membership to add access.'=>'استخدام عضوية المجموعة لحظر الوصول غير موصى به. ضع في اعتبارك تقليل قدرات الدور الخاص بالمستخدم واستخدام عضوية المجموعة لإضافة الوصول.','S